Devuelve SOLO JSON crudo: {"hallazgos":[{"gravedad":"alta|media|baja","donde":"...","problema":"...","fix":"cambio concreto"}]}. Máx 8, solo defectos REALES accionables. Enfoque: el bloque persona()/estiloDe/ARRANQUES/DIALECTOS/postura(): bugs, template literals rotos, hash colisiones, casos borde (dossier vacío, OPC raro).

CÓDIGO:
```
<!DOCTYPE html>
<!--
THESIS: interrogar a un país sintético construido con sus datos reales — no un
dashboard de cifras sino gente (simulada) que responde.
OWN-WORLD: hereda el mundo pixel del visor (baseplate azul-noche, Silkscreen,
bordes chunky, colores por estado); aquí los protagonistas son los residentes.
STORY: eliges un departamento, ves quién lo habita (números DANE reales vs la
población sintética), y le preguntas lo que quieras: 8 residentes contestan en
personaje y la postura se cuenta en vivo. Disclaimer siempre visible: simulación.
FIRST VIEWPORT: header con selector de departamento; izquierda el censo del dpto
(pirámide real vs sintética, régimen, economía); centro la encuesta con las
respuestas llegando; derecha la ficha del dpto (dossier) y residentes de muestra.
FORM: continuación del arcade-mission-control del visor, pinneado por Daniel.
-->
<html lang="es">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Sim Colombia</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Silkscreen:wght@400;700&family=Saira:wdth,wght@75..100,300..700&display=swap" rel="stylesheet">
<style>
:root{--bg:#10141f;--panel:#161b29;--panel2:#131724;--grid:#1e2436;--text:#eef0f4;
--dim:#9aa3b8;--faint:#7d879c;--work:#ffd23e;--ok:#59d97e;--fail:#ff5c5c;
--accent:#5aa7ff;--muj:#ff6fa5;--hom:#4dd6c1;--px:3px}
*{margin:0;padding:0;box-sizing:border-box}
body{background:var(--bg);color:var(--text);font-family:"Saira",system-ui,sans-serif;
font-stretch:90%;font-size:13px;min-height:100vh}
.pxf{font-family:"Silkscreen",monospace}
.panel{background:var(--panel);border:var(--px) solid var(--grid)}
.panel>h2{font-family:"Silkscreen";font-size:10px;color:var(--dim);padding:7px 10px 5px;
border-bottom:var(--px) solid var(--grid);text-transform:lowercase;display:flex;justify-content:space-between;flex-wrap:wrap;gap:4px 8px}
select,button,input{background:var(--panel2);color:var(--text);border:2px solid var(--grid);
font:inherit;font-size:12.5px;padding:5px 9px;cursor:pointer}
select:focus-visible,button:focus-visible,input:focus-visible{outline:2px solid var(--work)}
.pxbtn{font-family:"Silkscreen";font-size:10px;box-shadow:2px 2px 0 #000a}
.pxbtn:active{transform:translate(2px,2px);box-shadow:none}

#app{max-width:1500px;margin:0 auto;padding:8px;display:grid;gap:8px;
grid-template-columns:340px 1fr 320px;
grid-template-areas:"top top top" "censo encuesta ficha" "banner banner banner"}
#top{grid-area:top;display:flex;align-items:center;gap:14px;padding:8px 12px;
background:var(--panel);border:var(--px) solid var(--grid);flex-wrap:wrap}
#title{font-family:"Silkscreen";font-weight:700;font-size:16px;color:var(--work);
text-shadow:3px 3px 0 #0007}
#title small{color:var(--accent);font-size:16px}
#dptosel{min-width:250px;font-size:13.5px;padding:7px 10px;border-color:var(--work)}
#kpis{margin-left:auto;display:flex;gap:18px;text-align:right}
#kpis div b{display:block;font-family:"Silkscreen";font-size:12px;color:var(--text);font-weight:400}
#kpis div span{font-size:10px;color:var(--faint)}
a.back{color:var(--faint);text-decoration:none;font-size:11px}
a.back:hover{color:var(--work)}

#censo{grid-area:censo;display:flex;flex-direction:column;gap:8px;background:none;border:none}
#censo .panel{display:flex;flex-direction:column;min-height:0}
#censo .body{padding:12px 14px;overflow-y:auto}
/* mapa-navegador: el país siempre a la vista, clic = elegir territorio */
#navmap{padding:8px 8px 4px;position:relative}
#navmap svg{width:100%;height:auto;display:block}
#navmap path{fill:var(--panel2);stroke:#2a3350;stroke-width:1.2;cursor:pointer;transition:fill .22s,stroke .15s}
#navmap svg{filter:drop-shadow(0 5px 0 #00000055)}
#navmap path:hover{stroke:var(--work);stroke-width:2}
#navmap path:focus-visible,#navmap path:focus{outline:2px solid var(--work);outline-offset:1px}
#navmap path.sel{stroke:var(--work);stroke-width:2.5;filter:drop-shadow(0 0 4px #ffd23e66)}
#navmap path.fav{fill:color-mix(in srgb,var(--ok) 45%,var(--panel2))}
#navmap path.con{fill:color-mix(in srgb,var(--fail) 45%,var(--panel2))}
#navmap path.dep{fill:color-mix(in srgb,var(--work) 40%,var(--panel2))}
#navmap path.hot{stroke:var(--work);stroke-width:2;animation:blink 1s steps(2) infinite}
#maplabel{font-family:"Silkscreen";font-size:9px;color:var(--work);text-align:center;
padding:5px 0 3px;min-height:20px;letter-spacing:.06em}
#ctrl{display:none;gap:4px}
#ctrl button{font-family:"Silkscreen";font-size:8px;padding:3px 8px}
#ctrl button.pausa{color:var(--work);border-color:var(--work)}
#reloj{font-family:"Silkscreen";font-size:9px;color:var(--faint)}
.acuerdo{flex:1 1 100%;border:2px solid var(--grid);padding:6px 10px}
.acuerdo .t{display:flex;justify-content:space-between;font-size:10.5px;color:var(--dim);margin-bottom:4px}
.acuerdo .t b{font-family:"Silkscreen";font-size:10px;color:var(--text);font-weight:400}
.acuerdo .g{height:10px;background:var(--panel2);border:1px solid var(--grid);display:flex}
.acuerdo .g i{height:100%}
h3{font-family:"Silkscreen";font-size:9px;color:var(--faint);margin:18px 0 8px;font-weight:400;display:flex;align-items:center;gap:8px}
h3::after{content:"";flex:1;height:2px;background:var(--grid)}
h3:first-child{margin-top:0}
.pyr{display:grid;grid-template-columns:1fr 36px 1fr;gap:3px 8px;font-size:10px;padding:2px 0 4px}
.pyr .lab{color:var(--faint);text-align:center;font-family:"Silkscreen";font-size:7px;padding-top:1px}
.pyr .bar{position:relative;height:13px;background:var(--panel2);border:1px solid var(--grid)}
.pyr .bar i{position:absolute;top:1px;bottom:1px;opacity:.9}
.pyr .bar.l i{right:0;background:var(--hom)}
.pyr .bar.r i{left:0;background:var(--muj)}
.pyr .bar s{position:absolute;top:-1px;bottom:-1px;width:2px;background:var(--text);opacity:.85}
.leyenda{display:flex;gap:14px;font-size:10px;color:var(--faint);margin-top:6px}
.leyenda i{display:inline-block;width:9px;height:9px;vertical-align:-1px;margin-right:4px}
.hbar{margin:7px 0}
.hbar .t{display:flex;justify-content:space-between;font-size:11.5px;color:var(--dim)}
.hbar .t b{font-family:"Silkscreen";font-size:10px;color:var(--text);font-weight:400}
.hbar .g{height:12px;background:var(--panel2);border:1px solid var(--grid);position:relative}
.hbar .g i{position:absolute;inset:1px auto 1px 1px;background:var(--accent)}
.fuente{font-size:9.5px;color:var(--faint);margin-top:2px}

#encuesta{grid-area:encuesta;display:flex;flex-direction:column;min-height:74vh}
#encuesta>h2>span{min-width:0}
#estado{overflow-wrap:anywhere}
#modo{display:flex;gap:4px;flex:0 0 auto}
#modo button{font-family:"Silkscreen";font-size:8px;padding:3px 8px;color:var(--faint)}
#modo button[aria-pressed="true"]{color:var(--work);border-color:var(--work)}
#resps{flex:1;overflow-y:auto;padding:10px;display:flex;flex-direction:column;gap:8px}
.resp{display:grid;grid-template-columns:38px 1fr;gap:9px;background:var(--panel2);box-shadow:2px 2px 0 #0006;
border:2px solid var(--grid);padding:8px;border-left:4px solid var(--pc,var(--grid));
max-width:92%;animation:entra .22s steps(3)}
.resp.alt{margin-left:auto;grid-template-columns:1fr 34px;border-left:2px solid var(--grid);
border-right:4px solid var(--pc,var(--grid))}
.resp.alt .px{order:2}.resp.alt>div{order:1;text-align:right}
@keyframes entra{from{transform:translateY(8px);opacity:0}}
.resp .who{font-family:"Silkscreen";font-size:8px;color:var(--dim);margin-bottom:3px}
.resp .say{font-size:12.5px;line-height:1.45}
.resp .say.thinking{color:var(--faint)}
.resp .say.thinking::after{content:"···";animation:blink .8s steps(2) infinite;
font-family:"Silkscreen";letter-spacing:2px}
.resp .px{width:34px;height:34px;image-rendering:pixelated}
/* ficha del residente: quién es según el DANE */
#rmask{position:fixed;inset:0;background:#000a;z-index:30;display:none;
align-items:center;justify-content:center}
#rmask.open{display:flex}
#rcard{width:min(420px,92vw);background:var(--panel);border:var(--px) solid var(--work);
box-shadow:8px 8px 0 #000c;animation:entra .2s steps(3)}
#rcard header{display:flex;gap:14px;padding:14px;border-bottom:var(--px) solid var(--grid);
align-items:center;background:var(--panel2)}
#rcard header canvas{width:80px;height:80px;image-rendering:pixelated;
background:var(--bg);border:2px solid var(--grid);padding:4px}
#rcard header .nm{font-family:"Silkscreen";font-size:12px;color:var(--work);line-height:1.6}
#rcard header .sub{font-size:12px;color:var(--dim)}
#rcard .rkv{display:grid;grid-template-columns:110px 1fr;gap:6px 12px;padding:12px 14px;font-size:12.5px}
#rcard .rkv b{font-family:"Silkscreen";font-size:8px;color:var(--faint);padding-top:3px}
#rcard .rkv .src{display:block;font-size:9.5px;color:var(--faint)}
#rcard footer{padding:8px 14px 12px;font-size:10.5px;color:var(--faint);
border-top:2px solid var(--grid)}
#rcard .cerrar{margin-left:auto;font-family:"Silkscreen";font-size:10px}
.resp,.seat,.res{cursor:pointer}

/* la mesa se arma: los vecinos llegan mientras se busca el contexto */
#seats{display:flex;flex-wrap:wrap;gap:6px;padding:4px 0 2px}
.seat{display:flex;align-items:center;gap:6px;background:var(--panel2);
border:2px solid var(--grid);padding:4px 9px 4px 5px;font-size:11px;color:var(--dim);
opacity:0;animation:llega .3s steps(4) forwards}
.seat canvas{width:22px;height:22px;image-rendering:pixelated}
@keyframes llega{0%{opacity:0;transform:translateY(-10px) scale(.6)}
60%{opacity:1;transform:translateY(2px) scale(1.08)}100%{opacity:1;transform:none}}
#ticker{font-size:12px;color:var(--dim);padding:6px 2px;display:flex;gap:8px;align-items:center}
#ticker::before{content:"";width:8px;height:8px;background:var(--work);
animation:tickblink .7s steps(2) infinite}
@keyframes tickblink{50%{opacity:.2}}
.ctx{border:2px solid var(--accent);border-left-width:5px;background:linear-gradient(180deg,color-mix(in srgb,var(--accent) 7%,var(--panel2)),var(--panel2));
padding:8px 12px 9px;font-size:12px;line-height:1.5;color:var(--text);;box-shadow:3px 3px 0 #0008;overflow-wrap:anywhere}
.ctx b{font-family:"Silkscreen";font-size:8px;color:var(--accent);display:block;margin-bottom:4px}
.ctx .cbody{white-space:pre-line;display:block}
.ctx.off{border-color:var(--grid);opacity:.85}
.mod{border:2px solid var(--accent);background:var(--panel2);padding:9px 12px;
font-size:12.5px;line-height:1.5;color:var(--dim)}
.mod b{font-family:"Silkscreen";font-size:8px;color:var(--accent);display:block;margin-bottom:4px}
/* mapa del país */
#mapa{display:grid;grid-template-columns:minmax(240px,340px) 1fr;gap:10px;min-height:0}
#mapa svg{width:100%;height:auto;max-height:66vh}
#mapa path{fill:var(--panel2);stroke:var(--grid);stroke-width:1;cursor:pointer;
transition:fill .25s}
#mapa path:hover{stroke:var(--work);stroke-width:1.5}
#mapa path.hot{stroke:var(--work);stroke-width:2;animation:blink 1s steps(2) infinite}
#mapa path.fav{fill:color-mix(in srgb,var(--ok) 45%,var(--panel2))}
#mapa path.con{fill:color-mix(in srgb,var(--fail) 45%,var(--panel2))}
#mapa path.dep{fill:color-mix(in srgb,var(--work) 40%,var(--panel2))}
#mesa{display:flex;flex-direction:column;gap:8px;overflow-y:auto;max-height:66vh;min-width:0}
#mesa .hint{color:var(--faint);padding:14px;text-align:center}
.conclu{border:2px solid var(--pc,var(--accent));background:var(--panel2);padding:9px 12px;
font-size:12.5px;line-height:1.5}
.conclu b{font-family:"Silkscreen";font-size:8px;display:block;margin-bottom:4px;color:var(--pc,var(--accent))}
.ronda{font-family:"Silkscreen";font-size:8px;color:var(--faint);text-align:center;
padding:4px 0;letter-spacing:.2em}
@keyframes blink{50%{opacity:.3}}
#tally{display:flex;gap:8px;padding:8px 10px;flex-wrap:wrap}
#tally:not(:empty){border-bottom:var(--px) solid var(--grid)}
.tal{flex:1;min-width:110px;border:2px solid var(--grid);padding:8px 9px 7px;text-align:center;
position:relative;background:var(--panel2);box-shadow:3px 3px 0 #0007}
.tal::before{content:"";position:absolute;top:3px;left:3px;width:6px;height:6px;background:var(--grid)}
.tal.fav::before{background:var(--ok)}.tal.con::before{background:var(--fail)}.tal.dep::before{background:var(--work)}
.tal b{font-family:"Silkscreen";font-size:18px;display:block;font-weight:700;animation:pop2 .2s steps(3)}
@keyframes pop2{from{transform:scale(1.5)}}
.tal span{font-size:10px;color:var(--faint);text-transform:lowercase;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;display:block}
.tal.fav{border-color:var(--ok)} .tal.fav b{color:var(--ok)}
.tal.con{border-color:var(--fail)} .tal.con b{color:var(--fail)}
.tal.dep{border-color:var(--work)} .tal.dep b{color:var(--work)}
#qbar{display:flex;flex-wrap:wrap;gap:6px;padding:10px;border-bottom:2px solid var(--grid)}
#qin{flex:1 1 100%;min-width:0}
#qbar select,#qbar button{flex:0 0 auto}
#modohelp{font-size:11px;color:var(--work);padding:7px 10px 0;letter-spacing:.02em}
#selinfo{font-size:11.5px;color:var(--dim);padding:4px 10px 6px;border-bottom:2px solid var(--grid)}
#selinfo b{font-family:"Silkscreen";font-size:8px;color:var(--faint)}
#selinfo .chip{display:inline-block;border:1px solid var(--work);color:var(--work);
padding:1px 4px 1px 8px;margin:1px 3px}
#selinfo .chip .chip-x{cursor:pointer;font-style:normal;padding:0 4px;margin:0;background:none;border:0;font:inherit;font-size:inherit;line-height:1;color:var(--dim)}
#selinfo .chip .chip-x:hover{color:var(--fail)}
#selinfo button{font-size:10px;padding:1px 7px;margin-left:6px;color:var(--dim)}
#sugg{display:flex;flex-wrap:wrap;gap:4px;padding:0 10px 10px}
#sugg button{font-size:10.5px;padding:2px 8px;color:var(--dim)}
#sugg button:hover{color:var(--work);border-color:var(--work)}

#ficha{grid-area:ficha;display:flex;flex-direction:column;gap:8px}
#ficha .body{padding:10px;font-size:12px;line-height:1.5;color:var(--dim)}
#ficha .body b{color:var(--text);font-weight:500}
#ficha .tag{display:inline-block;border:1px solid var(--grid);padding:1px 7px;
margin:2px 3px 2px 0;font-size:10.5px;color:var(--dim)}
#muestra{display:grid;grid-template-columns:1fr 1fr;gap:4px;padding:8px}
.res{display:flex;gap:6px;align-items:center;background:var(--panel2);
border:1px solid var(--grid);padding:4px 6px;font-size:10.5px;color:var(--dim)}
.res canvas{width:20px;height:20px;image-rendering:pixelated}

#banner{grid-area:banner;text-align:center;font-size:10.5px;color:var(--faint);
padding:6px;border:1px dashed var(--grid)}
@media(max-width:1000px){#app{grid-template-columns:1fr;
grid-template-areas:"top" "encuesta" "censo" "ficha" "banner"}#kpis{display:none}}
</style>
</head>
<body>
<div id="app">
  <header id="top">
    <span id="title">SIM<small>▸</small>COLOMBIA</span>
    <select id="dptosel" aria-label="Departamento"></select>
    <a class="back" href="../">◂ visor del enjambre</a>
    <div id="kpis"></div>
    <button id="gear" class="pxbtn">AJUSTES</button>
  </header>

  <section id="censo">
    <div class="panel"><h2>colombia <b id="maptag">toca un territorio</b></h2>
      <div id="navmap" aria-busy="true"><div class="pxf" style="color:var(--faint);padding:24px;text-align:center">cargando 33 territorios…</div></div><div id="maplabel">—</div>
    </div>
    <div class="panel" style="flex:1"><h2>el censo <b id="c-src-tag">DANE</b></h2>
      <div class="body" id="censobody" aria-busy="true"><div class="fuente">cargando censo DANE…</div></div>
    </div>
  </section>

  <section id="encuesta" class="panel">
    <h2><span>la conversación <b id="estado"></b> <span id="reloj"></span></span>
      <span id="ctrl"><button id="btnpausa" type="button">⏸ PAUSAR</button><button id="btnfin" type="button">■ CERRAR</button></span>
      <span id="modo"><button data-m="pais" aria-pressed="false">PAÍS</button><button data-m="tertulia" aria-pressed="true">TERTULIA</button><button data-m="sondeo" aria-pressed="false">SONDEO</button></span></h2>
    <div id="modohelp"></div>
    <div id="selinfo"></div>
    <form id="qbar">
      <input id="qin" placeholder="pregúntale al país lo que quieras… (toca una sugerencia y edítala)" autocomplete="off" style="font-size:13.5px;padding:8px 11px">
      <select id="nsel" aria-label="Tamaño del panel" style="flex:0 0 auto">
        <option value="8">8 voces</option><option value="12">12 voces</option>
        <option value="20">20 voces</option>
      </select>
      <button class="pxbtn" type="submit">PREGUNTAR</button>
    </form>
    <div id="sugg"></div>
    <div id="tally"></div>
    <div id="resps"><div style="color:var(--faint);padding:16px;text-align:center;line-height:2">
      <b style="color:var(--work)">1.</b> toca territorios en el mapa (uno, varios, o ninguno = todo el país)<br>
      <b style="color:var(--work)">2.</b> elige el tipo de conversación arriba a la derecha<br>
      <b style="color:var(--work)">3.</b> suelta tu pregunta abajo — y míralos hablar</div></div>

  </section>

  <aside id="ficha">
    <div class="panel"><h2>la tierra</h2><div class="body" id="dossier" aria-busy="true"><div class="fuente">cargando dossier…</div></div></div>
    <div class="panel"><h2>residentes de muestra</h2><div id="muestra" aria-busy="true"><div class="fuente">cargando censo DANE…</div></div></div>
  </aside>

  <div id="banner">⚠ SIMULACIÓN — residentes sintéticos generados de marginales reales
  (DANE / datos.gov.co). Las opiniones son de personajes verosímiles, no de personas.
  Reporte de fidelidad: <a href="validacion.json" style="color:var(--dim)">validacion.json</a></div>
</div>

<div id="rmask"><div id="rcard">
  <header><canvas id="rpx" width="16" height="16"></canvas>
    <div><div class="nm" id="rnom"></div><div class="sub" id="rsub"></div></div>
    <button class="pxbtn cerrar" onclick="document.getElementById('rmask').classList.remove('open')">X</button></header>
  <div class="rkv" id="rkv"></div>
  <footer>Perfil muestreado de los marginales REALES de su territorio — cada dato con su fuente. Persona sintética: no existe, pero su demografía sí.</footer>
</div></div>

<div id="cfg" style="position:fixed;top:56px;right:8px;width:290px;z-index:9;display:none;
background:var(--panel);border:var(--px) solid var(--grid);padding:14px;box-shadow:6px 6px 0 #000a">
  <label style="font-family:Silkscreen;font-size:8px;color:var(--faint)">openrouter key (encuesta)</label>
  <input id="c-orkey" style="width:100%" placeholder="sk-or-v1-…">
</div>

<script>
const $=s=>document.querySelector(s);
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
let cfg={orkey:""};
try{cfg={...cfg,...JSON.parse(localStorage.getItem("sim-cfg")||"{}")};
  if(!cfg.orkey){const ag=JSON.parse(localStorage.getItem("ag-cfg")||"{}");if(ag.orkey)cfg.orkey=ag.orkey;}}catch(e){}
// clave local (solo existe en la máquina de Daniel; gitignoreada)
if(!cfg.orkey)fetch("../assets/local_keys.json").then(r=>r.json())
  .then(d=>{if(d.openrouter)cfg.orkey=d.openrouter}).catch(()=>{});
$("#gear").onclick=e=>{e.stopPropagation();const c=$("#cfg");c.style.display=c.style.display==="none"?"block":"none"};
document.addEventListener("click",e=>{if(!$("#cfg").contains(e.target)&&e.target.id!=="gear")$("#cfg").style.display="none"});
$("#c-orkey").onchange=e=>{cfg.orkey=e.target.value.trim();try{localStorage.setItem("sim-cfg",JSON.stringify(cfg))}catch(_){}};

/* controles de la deliberación */
let CONV={paused:false,stop:false,start:0};
let RUN=0;
/* aborta cualquier corrida viva: invalida su token, suelta la pausa y devuelve los controles */
function abortarCorrida(){RUN++;CONV.stop=true;CONV.paused=false;
  $("#ctrl").style.display="none";$("#reloj").textContent="";
