let CTX={q:null,txt:null,ok:false};  // fail-closed: sin verificación tipada de Jev, el contexto NUNCA se rotula como real
async function contexto(q){
  if(CTX.q===q)return CTX.txt;
  CTX={q,txt:null,ok:null};
  // la rama `online:true` es la reserva más cara (~$0.02): no se dispara sin pregunta
  // real ni con texto desmedido — el cupo se cobra al recibir, no al responder el 400
  if(typeof q!=="string"||!q.trim()||q.length>400){CTX={q:null,txt:null,ok:null};return null;}
  try{
    const SIS="HOY es 21 de septiembre de 2026. Interpreta el TEMA como lo entendería un colombiano de a pie (ej: 'Millonarios o Santa Fe' es la rivalidad futbolera de siempre, principalmente fútbol masculino, no solo la noticia del día). Busca noticias recientes de Colombia y devuelve SOLO 2-3 viñetas ULTRA CORTAS (máx 16 palabras) con hechos EXPLÍCITOS de fuentes, cada una cerrando con el medio entre paréntesis, ej (El Tiempo) — JAMÁS URLs. Si un dato no cuadra con la fecha, exclúyelo. Empieza directo con '- '. PROHIBIDO opinar o presentarte. Sin nada: SIN_NOVEDADES.";
    const pide=u=>fetch("/api/opina",{method:"POST",headers:{"Content-Type":"application/json"},
        body:JSON.stringify({online:true,max_tokens:260,messages:[
          {role:"system",content:SIS},{role:"user",content:u}]})})
      .then(r=>r.ok?r.json():null).then(j=>j?.content||"").catch(()=>"");
    // DOS búsquedas en paralelo: la noticia del momento + el panorama de fondo
    const [c1,c2]=await Promise.all([
      pide("TEMA: "+q+" (Colombia, septiembre 2026)"),
      pide("TEMA: panorama de fondo y datos clave de: "+q+" (Colombia, el ángulo que la gente discute normalmente)")]);
    const vi=[...new Set((c1+"\n"+c2).split("\n").map(s=>s.trim())
      .filter(s=>s.startsWith("- ")&&!/SIN_NOVEDADES/.test(s)))].slice(0,5);
    CTX.txt=vi.length?vi.join("\n"):null;
    /* Jev verifica el contexto antes de mostrarlo (fechas/consistencia) */
    if(CTX.txt){
      try{
        const v=await fetch("/api/opina",{method:"POST",headers:{"Content-Type":"application/json"},
          body:JSON.stringify({decide:true,
            state:"HOY: 21 septiembre 2026. Resumen noticioso a verificar:\n"+CTX.txt,
            questions:{fiable:{type:"noul",instructions:
              "Las viñetas son internamente consistentes, coherentes con la fecha de hoy (sin cargos o mandatos vencidos presentados como vigentes, sin fechas imposibles) y suenan a hechos citados, no a invención"}}})});
        if(v.ok){const j=await v.json();
          const n=j?.answers?.fiable?.noul;
          // sin `answers.fiable` tipado no hay verificación: el contexto queda NO verificado
          CTX.ok=typeof n==="number"&&n>=0.5;}
      }catch(e){}
    }
  }catch(e){}
  return CTX.txt;
