    ]);
    DOS=await fetch("dossiers.json").then(r=>r.json()).catch(()=>({}));
  }catch(e){$("#censobody").textContent="corre el pipeline: generate_population.py";return;}
  const sel=$("#dptosel");
  sel.innerHTML=`<option value="CO">★ Toda Colombia (panel nacional)</option>`+
    Object.entries(MARG).sort((a,b)=>a[1].nombre.localeCompare(b[1].nombre))
    .map(([c,d])=>`<option value="${c}" ${c===cur?"selected":""}>${esc(d.nombre)}</option>`).join("");
  sel.onchange=e=>{const v=e.target.value;
    if(v==="CO")SEL.clear();else{SEL=new Set([v]);cur=v;}
    syncSel();$("#maplabel").textContent=MARG[cur]?.nombre||"—";};
  drawNav();selInfo();
  $("#modohelp").textContent=MODOTXT[MODO];
  $("#kpis").innerHTML=`<div><b>${RES.length.toLocaleString()}</b><span>residentes</span></div>
    <div><b>33</b><span>territorios</span></div>
    <div><b>${(VAL.bloques_provisionales||[]).length?"parcial":"completa"}</b><span>base DANE</span></div>`;
  render();
  ["#navmap","#censobody","#dossier","#muestra","#sugg"].forEach(s=>$(s)?.removeAttribute("aria-busy"));
}

function natMarg(){
  const agg={nombre:"Colombia",edad:{},sexo:{hombre:0,mujer:0},poblacion:0,
    pib_sectores_pct:null,salud_pct:null,fuentes:{poblacion:"DANE proyecciones 2026, agregado nacional"}};
  for(const d of Object.values(MARG)){
    agg.poblacion+=d.poblacion||0;
    if(d.sexo){agg.sexo.hombre+=d.sexo.hombre;agg.sexo.mujer+=d.sexo.mujer;}
    if(d.edad)for(const[g,n]of Object.entries(d.edad))agg.edad[g]=(agg.edad[g]||0)+n;
  }
  if(!Object.keys(agg.edad).length){delete agg.edad;agg.sexo=null;}
  return agg;
}
/* marginales agregados de una selección: PIB y salud = media ponderada por población real */
function margDe(codes){
  if(codes.length===1)return MARG[codes[0]];
  const agg={nombre:codes.length+" territorios",edad:{},sexo:{hombre:0,mujer:0},poblacion:0,
    pib_sectores_pct:null,salud_pct:null,fuentes:{}};
  const pib={},sal={};let pibW=0,salW=0;
  for(const c of codes){
    const d=MARG[c];if(!d)continue;
    const w=d.poblacion||0;
    agg.poblacion+=w;
    if(d.sexo){agg.sexo.hombre+=d.sexo.hombre;agg.sexo.mujer+=d.sexo.mujer;}
    if(d.edad)for(const[g,n]of Object.entries(d.edad))agg.edad[g]=(agg.edad[g]||0)+n;
    if(d.pib_sectores_pct){for(const[s,v]of Object.entries(d.pib_sectores_pct))pib[s]=(pib[s]||0)+v*w;pibW+=w;}
    if(d.salud_pct){for(const[k,v]of Object.entries(d.salud_pct))if(typeof v==="number")sal[k]=(sal[k]||0)+v*w;salW+=w;}
  }
  if(pibW){agg.pib_sectores_pct={};
    for(const[s,v]of Object.entries(pib))agg.pib_sectores_pct[s]=+(v/pibW).toFixed(1);
    agg.fuentes.pib="media ponderada por población de "+codes.length+" territorios (DANE)";}
  if(salW){agg.salud_pct={};
    for(const[k,v]of Object.entries(sal))agg.salud_pct[k]=+(v/salW).toFixed(1);
    agg.fuentes.salud="media ponderada por población de "+codes.length+" territorios (DANE)";}
  agg.fuentes.poblacion="DANE proyecciones 2026, agregado de "+codes.length+" territorios";
  return agg;
}
/* memo por firma de selección: un solo pase O(n) sobre `mine` por repintado
