    const pide=u=>fetch("/api/opina",{method:"POST",headers:{"Content-Type":"application/json"},
        body:JSON.stringify({online:true,max_tokens:260,messages:[
          {role:"system",content:SIS},{role:"user",content:u}]})})
      .then(r=>r.ok?r.json():null).then(j=>j?.content||"").catch(()=>"");
    // DOS búsquedas en paralelo: la noticia del momento + el panorama de fondo
    const [c1,c2]=await Promise.all([
      pide("TEMA: "+q+" (Colombia, septiembre 2026)"),
      pide("TEMA: panorama de fondo y datos clave de: "+q+" (Colombia, el ángulo que la gente discute normalmente)")]);
    const vi=[...new Set((c1+"\n"+c2).split("\n").map(s=>s.trim())
      .filter(s=>s.startsWith("- ")&&!/SIN_NOVEDADES/.test(s)))].slice(0,5);
    CTX.txt=vi.length?vi.join("\n"):null;
    /* Jev verifica el contexto antes de mostrarlo (fechas/consistencia) */
    if(CTX.txt){
      try{
        const v=await fetch("/api/opina",{method:"POST",headers:{"Content-Type":"application/json"},
          body:JSON.stringify({decide:true,
            state:"HOY: 21 septiembre 2026. Resumen noticioso a verificar:\n"+CTX.txt,
            questions:{fiable:{type:"noul",instructions:
