  const rl = globalThis.__rl.get(ip)?.filter(t => now - t < 60000) || [];
  if (rl.length >= 30) return res.status(429).json({ error: "calma: máximo 30/min" });
  rl.push(now); globalThis.__rl.set(ip, rl);
