/* scroll coalescido: N typewriters → un solo layout por frame */
let pendScroll=false;const COLADOWN=new Set();
function scrollAbajo(el){
  COLADOWN.add(el);
  if(pendScroll)return;
  pendScroll=true;
  requestAnimationFrame(()=>{pendScroll=false;
    COLADOWN.forEach(e=>{e.scrollTop=1e9});COLADOWN.clear();});
}
function typewriter(el,txt){
  const host=el.closest("#resps,#mesa");
  el.classList.remove("thinking");el.textContent="";
  let i=0;const paso=Math.max(1,Math.round(txt.length/60));
  const iv=setInterval(()=>{
    i+=paso;el.textContent=txt.slice(0,i);
    if(host)scrollAbajo(host);
    if(i>=txt.length)clearInterval(iv);
  },28);
}
